import { glue } from "./engine.js";
export function glueRuns(runs, profile, options) {
    const result = runs.map((run) => ({ ...run }));
    let segment = [];
    function flush() {
        if (segment.length === 0)
            return;
        const text = segment.map((index) => result[index].text).join("");
        const corrected = glue(text, profile, options);
        let offset = 0;
        for (const index of segment) {
            const run = result[index];
            const length = run.text.length;
            run.text = corrected.slice(offset, offset + length);
            offset += length;
        }
        segment = [];
    }
    result.forEach((run, index) => {
        if (typeof run.text !== "string")
            throw new TypeError("Each Typehug run must have a string text property.");
        if (run.breakBefore || run.skip)
            flush();
        if (!run.skip)
            segment.push(index);
    });
    flush();
    return result;
}
